function txt(c) { return c.x.map(function (p) { return typeof p === "string" ? p : LAB.K(p[0], p[1]); }).join(" "); }
function keyboard() {
  LAB.ui.menu("Клавиатура", KB.filter(function (c) { return !c.desk || LAB.desktop; }).map(function (c) {
    return { label: c.t, fn: function () { LAB.ui.note(c.t, txt(c), keyboard); } };
  }).concat([{ label: "Назад", fn: open }]));
}

function open() {
  /* руководство открыли посреди чтения (F1 на главе или записке) — чтение
     обрывается, окно записки закрывается: иначе меню молчит, пока дочитывается текст */
  var tp = LAB.ui.top && LAB.ui.top();
  if (tp && tp.note) LAB.ui.closeTop(true);
  if (LAB.Speech.noteReading) LAB.Speech.endNote();
  var kb = LAB.kb(), items = [];
  CH.forEach(function (c, i) {
    if (c.touch && kb) return; /* на клавиатуре вместо жестов — «Клавиатура» */
    items.push({ label: c.t, fn: function () { LAB.ui.note(c.t, txt(c), open); } });
    if (i === 0 && kb) items.push({ label: "Клавиатура", fn: keyboard });
  });
  LAB.ui.menu("Руководство", items.concat([
    { label: "Что нового?", fn: function () { if (LAB.news) LAB.news.open(open); } },
    { label: "Бестиарий: мутанты и роботы", fn: bestiary },
    { label: "Оружие", fn: weapons },
    { label: "Броня", fn: armors },
    { label: "Назад", fn: function () {} }
  ]));
}
/* Сколько уровней игрок уже видел: в справочниках — только то, что встречается до этой глубины. */
function reachL() { var g = LAB.game && LAB.game.G; return Math.max(10, (LAB.game && LAB.game.entered && g && g.L) || 1); }
var foeL = null;
function foeDepth(id) {
  if (!foeL) { foeL = {}; for (var L = 1; L < LAB.LEVELS.length; L++) { var lv = LAB.LEVELS[L]; if (!lv) continue; lv.foes.forEach(function (f) { if (!foeL[f]) foeL[f] = L; }); if (LAB.BOSSES[lv.boss] && !foeL["boss:" + lv.boss]) foeL["boss:" + lv.boss] = L; } }
  return foeL[id] || 1;
}
function bestiary() {
  var items = [], maxL = reachL();
  ["bio", "mech", "anom"].forEach(function (kind) {
    for (var id in LAB.FOES) {
      var f = LAB.FOES[id];
      if (f.kind !== kind || foeDepth(id) > maxL) continue;
      items.push({ label: (kind === "mech" ? "Робот: " : kind === "anom" ? "Аномалия: " : "Мутант: ") + f.n, fn: (function (ff) { return function () { LAB.ui.note(ff.n, ff.desc + " Удар: " + LAB.ATK_T[ff.adt || "phys"] + ". " + (ff.kind === "mech" ? "Ионы, электрошок и ЭМИ — лучшее против него." : ff.kind === "anom" ? "Обычное оружие его почти не берёт: нужны позитроны, звук, фаза или гравитация." : "Магнетрон, плазма и жар — лучшее против него."), bestiary); }; })(f) });
    }
  });
  items.push({ label: "Модификации роботов", fn: function () {
    var t = []; for (var k in LAB.AFFIX) t.push(LAB.AFFIX[k].m + " — " + LAB.AFFIX[k].desc);
    LAB.ui.note("Модификации роботов", "Чем глубже, тем чаще роботы выходят с модификациями. " + t.join(". ") + ".", bestiary);
  } });
  items.push({ label: "Стражи шлюзов", fn: function () {
    var t = [], maxL = reachL(); for (var k in LAB.BOSSES) if (foeDepth("boss:" + k) <= maxL) t.push(LAB.BOSSES[k].n + ": " + LAB.BOSSES[k].desc);
    LAB.ui.note("Стражи", t.join(" "), bestiary);
  } });
  items.push({ label: "Назад", fn: open });
  LAB.ui.menu("Бестиарий", items);
}
function weapons() {
  var items = [];
  var maxL = reachL();
  for (var id in LAB.WEAPONS) {
    var w = LAB.WEAPONS[id];
    if ((LAB.WEAPON_DEPTH[id] || 1) > maxL) continue;
    items.push({ label: w.n.charAt(0).toUpperCase() + w.n.slice(1) + ", с уровня " + (LAB.WEAPON_DEPTH[id] || 1), fn: (function (ww) { return function () { LAB.ui.note(ww.n, ww.desc + " Урон — " + LAB.DTYPE_N[ww.dt] + ", дальность " + ww.rng + (ww.ammo !== "none" ? ", питание — " + LAB.AMMO[ww.ammo].n.toLowerCase() : ", без батарей") + ".", weapons); }; })(w) });
  }
  items.push({ label: "Назад", fn: open });
  LAB.ui.menu("Оружие", items);
}
function armors() {
  var items = [];
  var maxL = reachL();
  for (var id in LAB.ARMORS) {
    var a = LAB.ARMORS[id];
    if (a.depth > maxL) continue;
    items.push({ label: a.n.charAt(0).toUpperCase() + a.n.slice(1) + ", с уровня " + a.depth, fn: (function (aa) { return function () {
      var r = []; for (var t in aa.res) r.push(LAB.ATK_T[t] + " " + Math.round(aa.res[t] * 100) + "%");
      LAB.ui.note(aa.n, aa.desc + " Защита " + aa.def + " на первом уровне, глубже — больше. Стойкость: " + (r.join(", ") || "нет") + "." + (aa.special ? " Особенность: " + LAB.ARMOR_SPECIAL[aa.special] + "." : ""), armors);
    }; })(a) });
  }
  items.push({ label: "Назад", fn: open });
  LAB.ui.menu("Броня", items);
}

